const input=$json.body??$json;
const headers=$json.headers??{};
const expectedApiKey=String($env.CTF_API_KEY??'').trim();
const suppliedApiKey=String(headers['x-api-key']??(String(headers.authorization??'').replace(/^Bearer\s+/i,''))).trim();
if(!expectedApiKey) throw new Error('Server configuration error: CTF_API_KEY is not configured.');
if(!suppliedApiKey||suppliedApiKey!==expectedApiKey) throw new Error('Unauthorized request.');
const target=String(input.target_url??input.url??input.target??'').trim();
const task=String(input.task??input.message??'Run an authorized CTF web assessment and identify the flag.').trim();
const sessionId=String(input.session_id??`ctf-${Date.now()}-${Math.random().toString(36).slice(2,8)}`);
if(!target) throw new Error('Missing target_url.');
if(!/^https?:\/\//i.test(target)) throw new Error('target_url must use http:// or https://.');
if(target.length>2048) throw new Error('target_url is too long.');
let parsed;
try{parsed=new URL(target);}catch{throw new Error('Invalid target_url.');}
if(parsed.username||parsed.password) throw new Error('Target URLs with embedded credentials are not allowed.');
const allowed=String($env.CTF_ALLOWED_HOSTS??'').split(',').map(v=>v.trim().toLowerCase()).filter(Boolean);
if(allowed.length===0) throw new Error('Server configuration error: CTF_ALLOWED_HOSTS is not configured.');
const hostname=parsed.hostname.toLowerCase();
if(!allowed.includes(hostname)) throw new Error('Target is outside the configured CTF scope.');
const now=Date.now();
const windowMs=Math.max(1000,Number($env.CTF_RATE_LIMIT_WINDOW_SECONDS??300)*1000);
const globalMax=Math.max(1,Number($env.CTF_RATE_LIMIT_MAX_REQUESTS??10));
const sessionMax=Math.max(1,Number($env.CTF_SESSION_RATE_LIMIT_MAX_REQUESTS??5));
const state=$getWorkflowStaticData('global');
state.requests=Array.isArray(state.requests)?state.requests:[];
state.requests=state.requests.filter(r=>now-r.ts<windowMs);
if(state.requests.length>=globalMax) throw new Error('Rate limit exceeded. Try again later.');
const sessionCount=state.requests.filter(r=>r.sessionId===sessionId).length;
if(sessionCount>=sessionMax) throw new Error('Session rate limit exceeded.');
state.requests.push({ts:now,sessionId});
return [{json:{target_url:target,task,session_id:sessionId,scope_validated:true,authenticated:true,request_started_at:new Date(now).toISOString()}}];

const flag=String($json.output?.Flag??'').trim();
const evidence=String($json.output?.Evidence??'').trim();
const method=String($json.output?.['Capture Method']??'').trim();
const result={flag,evidence,capture_method:method,flag_found:Boolean(flag),completed_at:new Date().toISOString()};
return [{json:result}];
